import{erodeAlpineGrid,setAlpineDetailSnapshot}from"./alpine-erosion.js?v=i15-mw30beoi";self.onmessage=({data:{input,detail}})=>{try{setAlpineDetailSnapshot(detail);const steps=erodeAlpineGrid(input);let step=steps.next();for(;!step.done;)step=steps.next();const result=step.value,buffers=Object.values(result).filter(ArrayBuffer.isView).map(array=>array.buffer);self.postMessage({result},buffers)}catch{self.postMessage({result:null})}};